from pathlib import Path
import json,hashlib,subprocess,datetime,plistlib,os,sys
mode=sys.argv[1];assert mode in ('before','after');out=Path('evidence/no-api8/final');out.mkdir(parents=True, exist_ok=True);git=lambda *a:subprocess.check_output(['git',*a],text=True).strip();h=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();keys=sorted(set(subprocess.check_output(['git','ls-files','Sources','Package.swift','tests','scripts','packaging','contracts','.github/workflows','docs/V1-INSTALL.md'],text=True).splitlines()));head=git('rev-parse','HEAD');assert head==os.environ['SAYTILE_EXPECTED_REVISION'];utc=datetime.datetime.now(datetime.timezone.utc).isoformat();state={'utc':utc,'head':head,'tree':git('rev-parse','HEAD^{tree}'),'source_sha256':{k:h(k) for k in keys},'runtime_diff':git('diff','HEAD','--name-only','--','Sources','Package.swift','tests','scripts','packaging').splitlines()};assert not state['runtime_diff'];
if mode=='after':
 b=json.loads((out/'source-before.json').read_text());assert b['source_sha256']==state['source_sha256'] and b['head']==head and b['tree']==state['tree'];state['changed_files']=[]
(out/f'source-{mode}.json').write_text(json.dumps(state,indent=2)+'\n');canon='/Users/hhf/Documents/GitHub/saytile';app=Path('/Users/hhf/Applications/Saytile.app');pr={'utc':utc,'canonical_head':git('-C',canon,'rev-parse','HEAD'),'canonical_tracked_diff':git('-C',canon,'diff','HEAD','--name-only').splitlines(),'installed_source':plistlib.loads((app/'Contents/Info.plist').read_bytes())['SaytileSourceRevision'],'installed_binary_sha256':h(app/'Contents/MacOS/Saytile'),'rc1_dmg_sha256':h(Path(canon)/'dist/Saytile-1.0.0-rc.1-arm64.dmg')};(out/f'preservation-{mode}.json').write_text(json.dumps(pr,indent=2)+'\n');print(mode,head,len(keys),'inputs; installed source',pr['installed_source'])
